/* === inline === */

        

        /* Enable smooth scrolling for anchor links */
        html {
            scroll-behavior: smooth;
        }

        .whnz-wrap, .whnz-wrap * { box-sizing: border-box; margin: 0; padding: 0; }

        .whnz-wrap {
            font-family: 'Plus Jakarta Sans', sans-serif;
            background: #ffffff;
            overflow-x: hidden;
            color: #000000;
        }

        /* ── START TRANSITIONS (KEEP HERO AS-IS) ── */
        @keyframes whnzFadeUp {
            0% { opacity: 0; transform: translateY(30px); }
            100% { opacity: 1; transform: translateY(0); }
        }

        /* ORIGINAL: hero uses this (page-load animation) */
        .whnz-animate-up {
            opacity: 0; /* Hidden before animation starts */
            animation: whnzFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }

        /* Delays for cascading effect */
        .whnz-delay-1 { animation-delay: 0.1s; }
        .whnz-delay-2 { animation-delay: 0.2s; }
        .whnz-delay-3 { animation-delay: 0.3s; }
        .whnz-delay-4 { animation-delay: 0.4s; }
        .whnz-delay-5 { animation-delay: 0.5s; }
        .whnz-delay-6 { animation-delay: 0.6s; }

        /* NEW: scroll-in animation for WHY + PLANS only */
        .whnz-animate-scroll {
            opacity: 0;
            transform: translateY(30px);
        }
        .whnz-animate-scroll.whnz-inview {
            animation: whnzFadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }

        .whnz-eyebrow {
            font-family: 'Outfit', sans-serif;
            font-size: 11px;
            font-weight: 600;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            color: #0CC0DF;
            display: block;
            text-align: center;
            margin-bottom: 14px;
        }

        .whnz-heading {
            font-family: 'Outfit', sans-serif;
            font-weight: 800;
            color: #000000;
            letter-spacing: -0.025em;
            line-height: 1.08;
        }

        /* ── HERO ── */
        .elementor-2259 .whnz-hero {
            min-height: auto;
            background: #ffffff;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            overflow: hidden;
            /* Reduced top padding to move section UP on desktop */
            padding: 80px 40px 20px;
        }

        .elementor-2259 .whnz-hero::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image: radial-gradient(circle, rgba(12,192,223,0.15) 1px, transparent 1px);
            background-size: 32px 32px;
            pointer-events: none;
        }

        .elementor-2259 .whnz-hero::after {
            content: '';
            position: absolute;
            width: 800px; height: 800px;
            background: transparent;
            top: -200px; right: -200px;
            pointer-events: none;
        }

        .elementor-2259 .whnz-hero-inner {
            max-width: 1280px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            align-items: center;
            position: relative;
            z-index: 2;
            width: 100%;
        }

        .elementor-2259 .whnz-hero-left {
            /* Pushes the text right, closer to the map on desktop */
            margin-left: 60px;
        }

        .elementor-2259 .whnz-hero-tag {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            border: 1.5px solid rgba(12,192,223,0.4);
            background: rgba(12,192,223,0.05);
            backdrop-filter: blur(8px);
            padding: 7px 16px 7px 10px;
            border-radius: 100px;
            font-size: 12px;
            font-weight: 600;
            color: #000000;
            margin-bottom: 30px;
        }

        .elementor-2259 .whnz-hero-tag i {
            width: 20px; height: 20px;
            background: #0CC0DF;
            border-radius: 50%;
            display: inline-flex; align-items: center; justify-content: center;
            color: #ffffff; font-style: normal; font-size: 10px; font-weight: 700;
        }

        .elementor-2259 .whnz-hero h1 {
            font-family: 'Outfit', sans-serif;
            font-size: clamp(44px, 5vw, 72px);
