            padding: 15px 34px;
            border-radius: 10px;
            font-weight: 700;
            font-size: 13px;
            letter-spacing: 0.06em;
            text-transform: uppercase;
            transition: all 0.25s ease;
            display: inline-block;
            box-shadow: 0 4px 24px rgba(12,192,223,0.3);
