        .whnz-btn-solid:hover {
            background: #000000;
            box-shadow: 0 8px 36px rgba(0,0,0,0.45);
            transform: translateY(-2px);
        }

        .whnz-btn-ghost {
            background: transparent;
            color: #000000 !important;
            text-decoration: none !important;
            padding: 14px 34px;
            border-radius: 10px;
            font-weight: 600;
            font-size: 13px;
            letter-spacing: 0.06em;
            text-transform: uppercase;
            border: 2px solid #000000;
            transition: all 0.25s ease;
            display: inline-block;
        }
        .whnz-btn-ghost:hover {
            border-color: #0CC0DF;
            color: #0CC0DF !important;
        }

        /* Hero Image Container */
        .elementor-2259 .whnz-hero-right {
            display: flex;
            justify-content: flex-start;
            align-items: center;
            width: 100%;
            margin-left: -80px; /* Keeps map image horizontally the same */
        }

        .elementor-2259 .whnz-hero-img {
            max-width: 110%;
            height: auto;
            display: block;
            mix-blend-mode: multiply;
        }

        /* ── LOGO SLIDER (UNDER HERO) ── */
        .whnz-logo-slider {
            width: 100%;
            padding: 26px 0 10px;
            position: relative;
            z-index: 3;
        }

        .whnz-logo-slider-inner{
            max-width: 1280px;
            margin: 0 auto;
            padding: 0 40px;
        }

        .whnz-logo-marquee {
            overflow: hidden;
            width: 100%;
            position: relative;
        }

        .whnz-logo-track {
            display: flex;
            width: max-content;
            gap: 22px;
            animation: whnz-scroll 28s linear infinite;
        }

        .whnz-logo-slide {
            flex: 0 0 auto;
            width: 180px;
            height: 70px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: transparent;   /* no card */
            border: none;              /* no border */
            box-shadow: none;          /* no glow */
        }

        .whnz-logo-slide img {
            max-width: 155px;
            max-height: 52px;
            filter: grayscale(100%) brightness(0.55);
            opacity: 0.85;
        }

        /* Optional: color on hover */
        .whnz-logo-slide:hover img {
            filter: grayscale(0%) brightness(1);
            opacity: 1;
        }

        @keyframes whnz-scroll {
            from { transform: translateX(0); }
            to   { transform: translateX(-50%); }
        }

        /* Mobile */
        @media (max-width: 900px){
            .whnz-logo-slider-inner{ padding: 0 20px; }
            .whnz-logo-slide{ width: 170px; height: 80px; }
            .whnz-logo-track{ animation-duration: 22s; }
        }

        /* ── WHY CHOOSE US ── */
        .whnz-why {
            /* Reset to normal padding. Tight top padding keeps it close to the hero section */
            padding: 40px 40px 110px; 
            background: transparent; 
            position: relative;
            z-index: 3;
        }

        .whnz-why-hd { text-align: center; margin-bottom: 16px; }
        .whnz-why-hd h2 { font-size: clamp(28px, 3.5vw, 46px); margin-bottom: 14px; }

        .whnz-why-sub {
            text-align: center; font-size: 16px;
            color: rgba(0,0,0,0.7); max-width: 560px;
            margin: 0 auto 60px;
            line-height: 1.75;
        }

        .whnz-why-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 18px;
            max-width: 1280px;
            margin: 0 auto;
            position: relative; z-index: 1;
        }

        .whnz-why-card {
            background: rgba(255,255,255,0.7);
            border: 2px solid rgba(12,192,223,0.15);
            border-radius: 20px;
            padding: 34px 28px;
            backdrop-filter: blur(28px) saturate(150%);
            -webkit-backdrop-filter: blur(28px) saturate(150%);
            box-shadow: 0 4px 24px rgba(0,0,0,0.03);
            transition: all 0.32s ease;
            position: relative; overflow: hidden;
        }

        .whnz-why-card::before {
            content: '';
            position: absolute; inset: 0;
            background: linear-gradient(135deg, rgba(12,192,223,0.08) 0%, transparent 60%);
            opacity: 0; transition: opacity 0.3s;
