            margin-top: auto; /* Pushes button to bottom */
        }

        .whnz2-security-wrapper {
            max-width: 1280px;
            margin: 0 auto;
            padding: 60px 40px 100px; 
        }
        .whnz2-sec-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
            margin-bottom: 40px;
        }
        .whnz2-sec-card {
            background: #ffffff;
            border: 1px solid #eaedf3;
            border-radius: 16px;
            padding: 40px 30px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.02);
            transition: all 0.3s ease;
            height: 100%; /* EQUAL HEIGHT FIX */
        }
        .whnz2-sec-card:hover {
            border-color: #0CC0DF;
            box-shadow: 0 10px 30px rgba(12, 192, 223, 0.1);
        }
        .whnz2-sec-ico {
            width: 44px; height: 44px;
            background: rgba(12, 192, 223, 0.08);
            color: #0CC0DF;
            border-radius: 12px;
            display: flex; align-items: center; justify-content: center;
            margin-bottom: 20px;
        }
        .whnz2-sec-ico svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;}
        .whnz2-sec-card h4 {
            font-size: 18px;
            margin-bottom: 12px;
        }
        .whnz2-sec-card p {
            font-size: 14px;
            color: #5a6478;
        }

        .whnz2-sec-banner {
            background: #0CC0DF;
            border-radius: 20px;
            padding: 40px 50px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            color: #ffffff;
            gap: 30px;
            flex-wrap: wrap;
            box-shadow: 0 12px 30px rgba(12, 192, 223, 0.2);
        }
        .whnz2-sec-banner h3 {
            font-size: 20px;
            margin-bottom: 20px;
            color: #ffffff;
        }
        .whnz2-sec-list {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px 30px;
            list-style: none;
        }
        .whnz2-sec-list li {
            font-size: 14px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .whnz2-sec-list li svg {
            width: 18px; height: 18px;
            flex-shrink: 0;
            stroke: #ffffff;
            fill: none;
            stroke-width: 2;
            stroke-linecap: round;
            stroke-linejoin: round;
        }
        .whnz2-btn-white {
            background: #ffffff;
            color: #0CC0DF !important;
            text-decoration: none !important;
            padding: 16px 36px;
            border-radius: 10px;
            font-family: 'Outfit', sans-serif;
            font-weight: 800;
            font-size: 13px;
            letter-spacing: 0.05em;
            text-transform: uppercase;
            display: inline-block;
            transition: all 0.3s ease;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
        }
        .whnz2-btn-white:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
        }

        .whnz2-testi-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
        }
        .whnz2-testi-card {
            background: #f4fcff;
            border: 1px solid rgba(12, 192, 223, 0.2);
            border-radius: 20px;
            padding: 40px 30px;
            height: 100%; /* EQUAL HEIGHT FIX */
        }
        .whnz2-testi-user {
            display: flex;
            align-items: center;
            gap: 15px;
            margin-bottom: 20px;
        }
        .whnz2-testi-img {
            width: 50px; height: 50px;
            border-radius: 50%;
            object-fit: cover;
        }
        .whnz2-testi-info h4 {
            font-size: 16px;
            margin-bottom: 2px;
        }
        .whnz2-testi-info span {
            font-size: 12px;
            color: #0CC0DF;
            font-weight: 600;
        }
        .whnz2-testi-card p {
            font-style: italic;
            color: #5a6478;
            font-size: 14.5px;
        }

        .whnz2-faq-wrap {
            max-width: 800px;
            margin: 0 auto;
        }
        .whnz2-faq-item {
            background: #ffffff;
            border: 1px solid #eaedf3;
            border-radius: 12px;
            margin-bottom: 12px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.02);
            overflow: hidden;
        }
        .whnz2-faq-item summary {
            padding: 20px 25px;
            font-family: 'Outfit', sans-serif;
            font-weight: 700;
            font-size: 16px;
            color: #0a0f1e;
            cursor: pointer;
            list-style: none;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .whnz2-faq-item summary::-webkit-details-marker {
            display: none;
        }
        .whnz2-faq-item summary::after {
            content: '⌄';
            color: #8a94a6;
            font-size: 20px;
            transition: transform 0.3s ease;
        }
        .whnz2-faq-item[open] summary::after {
            transform: rotate(180deg);
        }
        .whnz2-faq-content {
            padding: 0 25px 20px;
            color: #5a6478;
            font-size: 15px;
            border-top: 1px solid transparent;
            line-height: 1.7;
        }
        .whnz2-faq-item[open] .whnz2-faq-content {
            border-top: 1px solid #eaedf3;
            padding-top: 20px;
        }

        /* ── RESPONSIVE ── */
        @media (max-width: 900px) {
            .whnz2-banner { flex-direction: column; text-align: center; padding: 40px 30px; }
            .whnz2-checklist { text-align: left; }
            .whnz2-grid-2 { grid-template-columns: 1fr; }
            .whnz2-comp-card { padding: 30px 20px; }
            .whnz2-sec-grid { grid-template-columns: 1fr; }
            .whnz2-sec-banner { flex-direction: column; text-align: left; padding: 30px; }
            .whnz2-sec-list { grid-template-columns: 1fr; }
            .whnz2-testi-grid { grid-template-columns: 1fr; }
        }
        @media (max-width: 600px) {
            .whnz2-container, .whnz2-migrate-wrapper, .whnz2-security-wrapper { padding: 60px 20px; }
            .whnz2-grid-4 { grid-template-columns: 1fr; }
            .whnz2-banner-wrapper { padding: 20px; }
            .whnz2-checklist { grid-template-columns: 1fr; }
            .whnz2-comp-row { grid-template-columns: 1fr 1fr; gap: 10px; }
            .whnz2-comp-row .header { display: none; }
            .whnz2-comp-val { text-align: right; }
        }
    

