/* Popup container - can be anything you want */
.popup {
  position: relative;
  display: inline-block;
  cursor: pointer;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}
/* The actual popup */
.popup .popuptext {
  visibility: hidden;
  width: 600px;
  background-color: #555;
  color: #fff;
  text-align: center;
  border-radius: 6px;
  padding: 8px 0;
  position: absolute;
  z-index: 1;
  bottom: 125%;
  left: 50%;
  margin-left: -80px;
  height: 250px;
  overflow-y: auto;
}
/* Popup arrow */
.popup .popuptext::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  margin-left: -5px;
  border-width: 5px;
  border-style: solid;
  border-color: #555 transparent transparent transparent;
}
/* Toggle this class - hide and show the popup */
.popup .show {
  visibility: visible;
  -webkit-animation: fadeIn 1s;
  animation: fadeIn 1s;
}
/* Add animation (fade in the popup) */
@-webkit-keyframes fadeIn {
  from {
     opacity: 0;
 }
  to {
     opacity: 1;
 }
}
@keyframes fadeIn {
  from {
     opacity: 0;
 }
  to {
     opacity:1 ;
 }
}

/* Nice Select */
.hostiko-select-field.nice-select {
  -webkit-tap-highlight-color: transparent;
  background-color: #fff;
  border-radius: 8px;
  box-sizing: border-box;
  clear: both;
  cursor: pointer;
  display: block;
  float: left;
  font-family: inherit;
  font-size: 14px;
  font-weight: normal;
  height: auto;
  line-height: 1.1em;
  outline: none;
  padding: 14px 20px;
  position: relative;
  text-align: left !important;
  -webkit-transition: all 0.2s ease-in-out;
  transition: all 0.2s ease-in-out;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
  white-space: nowrap;
  width: 100%;
  border: 1px solid #e9e9e9;
}
.hostiko-select-field.nice-select.open {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
.hostiko-select-field.nice-select:hover {
  border-color: #dbdbdb;
}
.hostiko-select-field.nice-select:active,
.hostiko-select-field.nice-select.open,
.hostiko-select-field.nice-select:focus {
  border-color: #e9e9e9;
}
.hostiko-select-field.nice-select:after {
  border-bottom: 2px solid #333333;
  border-right: 2px solid #333333;
  content: "";
  display: block;
  height: 7px;
  width: 7px;
  margin-top: -6px;
  pointer-events: none;
  position: absolute;
  right: 20px;
  top: 50%;
  -webkit-transform-origin: 66% 66%;
  -ms-transform-origin: 66% 66%;
  transform-origin: 66% 66%;
  -webkit-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  transform: rotate(45deg);
  -webkit-transition: all 0.15s ease-in-out;
  transition: all 0.15s ease-in-out;
}
.hostiko-select-field.nice-select.open:after {
  -webkit-transform: rotate(-135deg);
  -ms-transform: rotate(-135deg);
  transform: rotate(-135deg);
}
.hostiko-select-field.nice-select.open .list {
  opacity: 1;
  pointer-events: auto;
  -webkit-transform: scale(1) translateY(0);
  -ms-transform: scale(1) translateY(0);
  transform: scale(1) translateY(0);
}
.hostiko-select-field.nice-select.disabled {
