}
.hostiko-select-field.nice-select.small {
  font-size: 12px;
  height: 36px;
  line-height: 34px;
}
.hostiko-select-field.nice-select.small:after {
  height: 4px;
  width: 4px;
}
.hostiko-select-field.nice-select.small .option {
  line-height: 34px;
